head.script:
scwin.onpageload = function () {
    scwin.generateTestData();
    // localStorage에 저장된 모드가 있으면 초기 적용 (런타임 토글이 불완전한 케이스 대응)
    try {
        var savedMode = localStorage.getItem("wsq6284_initMode");
        if (savedMode) {
            var lv = $p.getComponentById("listView1");
            if (lv) {
                if (typeof lv.setAdaptiveMode === "function") lv.setAdaptiveMode(savedMode);
                if (lv._adaptiveMode !== undefined) lv._adaptiveMode = savedMode;
                if (lv.options && lv.options.adaptiveMode !== undefined) lv.options.adaptiveMode = savedMode;
                if (lv.opt && lv.opt.adaptiveMode !== undefined) lv.opt.adaptiveMode = savedMode;
                scwin._currentMode = savedMode;
                scwin.log("[초기화] localStorage에서 adaptiveMode = " + savedMode + " 적용");
                setTimeout(function () { window.dispatchEvent(new Event("resize")); }, 100);
            }
        }
    } catch (e) {}
    // DOM 렌더링 완료 후 상태 갱신 (즉시 + 약간 지연 모두 시도)
    scwin.updateStatus();
    setTimeout(scwin.updateStatus, 300);
    setTimeout(scwin.updateStatus, 1000);
};

scwin.getRandomDate = function () {
    var start = new Date(2000, 0, 1).getTime();
    var end = new Date(2025, 11, 31).getTime();
    var randomTime = start + Math.random() * (end - start);
    var date = new Date(randomTime);
    var year = date.getFullYear();
    var month = String(date.getMonth() + 1).padStart(2, "0");
    var day = String(date.getDate()).padStart(2, "0");
    return year + month + day;
};

scwin.generateTestData = function () {
    var data = [];

    for (var i = 0; i < 100; i++) {
        data.push({
            col_autocomplete: "OPT" + ((i % 3) + 1),
            col_anchor: "https://example.com/" + (i + 1),
            col_button: "Button" + (i + 1),
            col_calendar: scwin.getRandomDate(),
            col_checkcombobox: "OPT" + ((i % 3) + 1),
            col_checkbox: (i % 2 === 0) ? "Y" : "",
            col_image: "/cm/images/sample.jpg",
            col_inputbox: "입력값" + (i + 1),
            col_inputcalendar: scwin.getRandomDate(),
            col_radio: (i % 3 === 0) ? "R1" : ((i % 3 === 1) ? "R2" : "R3"),
            col_secret: "secret" + (i + 1),
            col_selectbox: "OPT" + ((i % 3) + 1),
            col_spinner: String((i + 1) * 10),
            col_textarea: "텍스트영역 내용 " + (i + 1) + "번째 행입니다.",
            col_textbox: "텍스트" + (i + 1),
            col_trigger: "Trigger" + (i + 1)
        });
    }

    dataList1.setJSON(data);
};

scwin.onpageunload = function () {
};

// ============================================================================
// WSQ-6284: adaptiveMode="self" 테스트 헬퍼
// ============================================================================

/* DOM 엘리먼트 안전 조회: HTMLElement만 반환 */
scwin.getDom = function (id) {
    var el = document.getElementById(id);
    if (el && el instanceof HTMLElement) return el;
    var comp = $p.getComponentById(id);
    if (!comp) return null;
    var cand = null;
    if (typeof comp.getElement === "function") cand = comp.getElement();
    else if (typeof comp.getEle === "function") cand = comp.getEle();
    else if (comp.element) cand = comp.element;
    else if (comp.domElement) cand = comp.domElement;
    return (cand && cand instanceof HTMLElement) ? cand : null;
};

/* 컨테이너 DOM 조회 — class 셀렉터 기반 (xf:group id가 DOM에 매핑 안 되는 케이스 대응) */
scwin.getContainerEl = function () {
    return document.querySelector(".list_container");
};

/* 컨테이너 너비 변경 (ListView 자체 너비를 바꿔서 self 모드 검증) */
scwin.setContainerWidth = function (px) {
    var el = scwin.getContainerEl();
    if (!el) {
        // 컨테이너 못 찾으면 ListView 자체 width를 직접 변경
        el = scwin.getListViewEl();
        if (el) {
            el.style.width = px + "px";
            scwin.log("[너비 변경] ListView 직접 = " + px + "px");
        } else {
            scwin.log("[너비 변경 실패] 대상 요소 없음");
            return;
        }
    } else {
        el.style.width = px + "px";
        scwin.log("[너비 변경] 컨테이너 = " + px + "px");
    }
    // self 모드에서 ListView가 자체 너비 변화를 감지하도록 트리거
    setTimeout(function () {
        var lv = $p.getComponentById("listView1");
        if (lv) {
            if (typeof lv.refresh === "function") lv.refresh();
            else if (typeof lv.redraw === "function") lv.redraw();
            else if (typeof lv._checkAdaptive === "function") lv._checkAdaptive();
            else if (typeof lv.adaptiveCheck === "function") lv.adaptiveCheck();
            else window.dispatchEvent(new Event("resize"));
        }
        scwin.updateStatus();
    }, 100);
};

scwin.btnW1200_onclick = function () { scwin.setContainerWidth(1200); };
scwin.btnW800_onclick  = function () { scwin.setContainerWidth(800); };
scwin.btnW600_onclick  = function () { scwin.setContainerWidth(600); };
scwin.btnW400_onclick  = function () { scwin.setContainerWidth(400); };
scwin.btnW300_onclick  = function () { scwin.setContainerWidth(300); };

/* adaptiveMode 토글: viewport <-> self (런타임 변경) */
scwin.btnToggleMode_onclick = function () {
    var lv = $p.getComponentById("listView1");
    if (!lv) return;
    var cur = (typeof lv.getAdaptiveMode === "function") ? lv.getAdaptiveMode()
            : (lv._adaptiveMode || scwin._currentMode || "self");
    var next = (cur === "self") ? "viewport" : "self";

    // 가능한 모든 경로로 mode 변경 적용
    var setterCalled = false;
    if (typeof lv.setAdaptiveMode === "function") { lv.setAdaptiveMode(next); setterCalled = true; }
    if (lv._adaptiveMode !== undefined) lv._adaptiveMode = next;
    if (lv.options && lv.options.adaptiveMode !== undefined) lv.options.adaptiveMode = next;
    if (lv.opt && lv.opt.adaptiveMode !== undefined) lv.opt.adaptiveMode = next;
    scwin._currentMode = next;

    scwin.log("[모드 변경] adaptiveMode = " + next + " (setAdaptiveMode " + (setterCalled ? "OK" : "없음 — 토글 불완전 가능") + ")");

    // 엔진 재평가 트리거
    setTimeout(function () {
        if (typeof lv.refresh === "function") lv.refresh();
        else if (typeof lv.redraw === "function") lv.redraw();
        else if (typeof lv._checkAdaptive === "function") lv._checkAdaptive();
        else if (typeof lv.adaptiveCheck === "function") lv.adaptiveCheck();
        window.dispatchEvent(new Event("resize"));
        scwin.updateStatus();
    }, 50);
};

/* viewport 모드로 페이지 재로딩 (런타임 토글 우회) */
scwin.btnReloadViewport_onclick = function () {
    try { localStorage.setItem("wsq6284_initMode", "viewport"); } catch (e) {}
    location.reload();
};
scwin.btnReloadSelf_onclick = function () {
    try { localStorage.setItem("wsq6284_initMode", "self"); } catch (e) {}
    location.reload();
};

/* ListView의 DOM 루트 조회 — id, class 순으로 시도 */
scwin.getListViewEl = function () {
    return scwin.getDom("listView1") || document.querySelector(".w2listView");
};

/* 현재 상태(브라우저 너비/ListView 너비/모드/모바일 여부) 표시 */
scwin.updateStatus = function () {
    try {
        var lv = $p.getComponentById("listView1");
        var lvEl = scwin.getListViewEl();
        var lvWidth = lvEl ? lvEl.offsetWidth : 0;
        var winWidth = window.innerWidth;
        var mode = (lv && typeof lv.getAdaptiveMode === "function") ? lv.getAdaptiveMode()
                 : ((lv && lv._adaptiveMode) || scwin._currentMode || "self");
        var threshold = 500;
        var isMobile = lvEl && lvEl.classList.contains("w2listView_mobile");

        var msg = "브라우저: " + winWidth + "px | ListView: " + lvWidth + "px | "
                + "adaptiveMode: " + mode + " | adaptiveThreshold: " + threshold + "px | "
                + "현재 뷰: " + (isMobile ? "[MOBILE]" : "[DESKTOP]");
        // textbox 컴포넌트: setLabel 우선, 없으면 setValue, 그것도 없으면 DOM 직접 변경
        var tb = $p.getComponentById("tbx_status");
        var updated = false;
        if (tb) {
            if (typeof tb.setLabel === "function") { tb.setLabel(msg); updated = true; }
            else if (typeof tb.setValue === "function") { tb.setValue(msg); updated = true; }
        }
        if (!updated) {
            var tbEl = document.getElementById("tbx_status");
            if (tbEl) tbEl.textContent = msg;
        }
    } catch (e) {
        console.warn("updateStatus error:", e);
    }
};

/* 로그 출력 */
scwin.log = function (msg) {
    var ta = $p.getComponentById("textarea_log");
    if (!ta) return;
    var time = new Date().toLocaleTimeString();
    var cur = ta.getValue() || "";
    ta.setValue(cur + "[" + time + "] " + msg + "\n");
};

scwin.btnClearLog_onclick = function () {
    var ta = $p.getComponentById("textarea_log");
    if (ta) ta.setValue("");
};

/* onadaptivechange 핸들러 — 모바일/데스크탑 전환 시 호출 */
scwin.listView1_onadaptivechange = function (info) {
    var lvEl = scwin.getListViewEl();
    var lvWidth = lvEl ? lvEl.offsetWidth : 0;
    var isMobile = lvEl && lvEl.classList.contains("w2listView_mobile");
    scwin.log("[onadaptivechange] " + (isMobile ? "[MOBILE]" : "[DESKTOP]") + " (ListView 너비 = " + lvWidth + "px)");
    setTimeout(scwin.updateStatus, 50);
};

/* 브라우저 리사이즈 시 상태 갱신 */
scwin.listView1_onpageindexchange = function () { };

/* 윈도우 리사이즈 감지 (viewport 모드 비교용) */
window.addEventListener("resize", function () {
    if (scwin.updateStatus) scwin.updateStatus();
});

// ============================================================================
// DataList API 테스트 (기존 기능 유지)
// ============================================================================

// setJSON: 전체 데이터 교체
scwin.btnSetJSON_onclick = function (e) {
    scwin.generateTestData();
    var pass = dataList1.getRowCount() === 100;
    console.log("[setJSON] " + dataList1.getRowCount() + "건 " + (pass ? "PASS" : "FAIL"));
    return pass;
};

// insertJSON: 특정 위치에 행 삽입
scwin.btnInsertJSON_onclick = function (e) {
    var before = dataList1.getRowCount();
    var data = [
        { col_autocomplete: "OPT3", col_button: "Button", col_calendar: "20260201", col_checkbox: "Y", col_checkcombobox: "OPT3", col_image: "/cm/images/sample2.png", col_inputbox: "삽입1", col_inputcalendar: "20260201", col_radio: "R1", col_secret: "1234", col_selectbox: "OPT3", col_spinner: "50", col_textarea: "텍스트영역", col_textbox: "텍스트", col_trigger: "Trigger", col_anchor: "링크" },
        { col_autocomplete: "OPT3", col_button: "Button", col_calendar: "20260202", col_checkbox: "", col_checkcombobox: "OPT3", col_image: "/cm/images/sample2.png", col_inputbox: "삽입2", col_inputcalendar: "20260202", col_radio: "R2", col_secret: "5678", col_selectbox: "OPT3", col_spinner: "100", col_textarea: "텍스트영역2", col_textbox: "텍스트2", col_trigger: "Trigger2", col_anchor: "링크2" }
    ];
    dataList1.insertJSON(0, data);
    var after = dataList1.getRowCount();
    var pass = (after === before + 2) && (dataList1.getCellData(0, 'col_inputbox') === '삽입1');
    console.log("[insertJSON] " + before + "→" + after + "건, 0행 InputBox=" + dataList1.getCellData(0, 'col_inputbox') + " " + (pass ? "PASS" : "FAIL"));
    return pass;
};

// setRowJSON: 특정 행 데이터 교체
scwin.btnSetRowJSON_onclick = function (e) {
    if (dataList1.getRowCount() === 0) { console.log("데이터 없음"); return false; }
    var rowData = { col_autocomplete: "OPT3", col_button: "수정", col_calendar: "20260301", col_checkbox: "", col_checkcombobox: "OPT3", col_image: "sample2.png", col_inputbox: "수정", col_inputcalendar: "20260301", col_radio: "R3", col_secret: "0000", col_selectbox: "OPT3", col_spinner: "999", col_textarea: "수정텍스트", col_textbox: "수정", col_trigger: "수정Trigger", col_anchor: "수정링크" };
    dataList1.setRowJSON(0, rowData, true);
    var pass = (dataList1.getCellData(0, 'col_textbox') === '수정') && (dataList1.getCellData(0, 'col_spinner') === '999');
    console.log("[setRowJSON] Textbox=" + dataList1.getCellData(0, 'col_textbox') + ", Spinner=" + dataList1.getCellData(0, 'col_spinner') + " " + (pass ? "PASS" : "FAIL"));
    return pass;
};

// setCellData: 특정 셀 데이터 수정
scwin.btnSetCellData_onclick = function (e) {
    if (dataList1.getRowCount() === 0) { console.log("데이터 없음"); return false; }
    dataList1.setCellData(0, "col_textbox", "셀수정됨");
    var pass = dataList1.getCellData(0, 'col_textbox') === '셀수정됨';
    console.log("[setCellData] Textbox=" + dataList1.getCellData(0, 'col_textbox') + " " + (pass ? "PASS" : "FAIL"));
    return pass;
};

// removeRow: 단일 행 삭제
scwin.btnRemoveRow_onclick = function (e) {
    if (dataList1.getRowCount() === 0) { console.log("데이터 없음"); return false; }
    var before = dataList1.getRowCount();
    dataList1.removeRow(0);
    var after = dataList1.getRowCount();
    var pass = after === before - 1;
    console.log("[removeRow] " + before + "→" + after + "건 " + (pass ? "PASS" : "FAIL"));
    return pass;
};

// removeRows: 여러 행 삭제
scwin.btnRemoveRows_onclick = function (e) {
    if (dataList1.getRowCount() < 2) { console.log("행 2개 이상 필요"); return false; }
    var before = dataList1.getRowCount();
    dataList1.removeRows([0, 1]);
    var after = dataList1.getRowCount();
    var pass = after === before - 2;
    console.log("[removeRows] " + before + "→" + after + "건 " + (pass ? "PASS" : "FAIL"));
    return pass;
};

// removeAll: 전체 삭제
scwin.btnRemoveAll_onclick = function (e) {
    dataList1.removeAll();
    var pass = dataList1.getRowCount() === 0;
    console.log("[removeAll] " + dataList1.getRowCount() + "건 " + (pass ? "PASS" : "FAIL"));
    return pass;
};

// ============================================================================
// 양방향 바인딩 테스트
// ============================================================================

scwin.BIND_COMPONENTS = [
    { compId: 'autoComplete1', colId: 'col_autocomplete', getter: 'getValue', setter: 'setValue', testValue: 'OPT2' },
    { compId: 'anchor1', colId: 'col_anchor', getter: 'getValue', setter: 'setValue', testValue: 'https://test.com' },
    { compId: 'button1', colId: 'col_button', getter: 'getLabel', setter: 'setLabel', testValue: '테스트버튼' },
    { compId: 'calendar1', colId: 'col_calendar', getter: 'getValue', setter: 'gotoCalendar', testValue: '20260315' },
    { compId: 'checkcombobox1', colId: 'col_checkcombobox', getter: 'getValue', setter: 'setValue', testValue: 'OPT1,OPT2' },
    { compId: 'checkbox1', colId: 'col_checkbox', getter: 'getValue', setter: 'setValue', testValue: 'Y' },
    { compId: 'image1', colId: 'col_image', getter: 'getSrc', setter: 'setSrc', testValue: '/cm/images/test.png' },
    { compId: 'input1', colId: 'col_inputbox', getter: 'getValue', setter: 'setValue', testValue: '테스트입력' },
    { compId: 'inputCalendar1', colId: 'col_inputcalendar', getter: 'getValue', setter: 'setValue', testValue: '20260315' },
    { compId: 'radio1', colId: 'col_radio', getter: 'getValue', setter: 'setValue', testValue: 'R2' },
    { compId: 'secret1', colId: 'col_secret', getter: 'getValue', setter: 'setValue', testValue: 'newpass' },
    { compId: 'selectbox1', colId: 'col_selectbox', getter: 'getValue', setter: 'setValue', testValue: 'OPT3' },
    { compId: 'spinner1', colId: 'col_spinner', getter: 'getValue', setter: 'setValue', testValue: '999' },
    { compId: 'textarea1', colId: 'col_textarea', getter: 'getValue', setter: 'setValue', testValue: '테스트텍스트영역' },
    { compId: 'textbox1', colId: 'col_textbox', getter: 'getValue', setter: 'setValue', testValue: '테스트텍스트' },
    { compId: 'trigger1', colId: 'col_trigger', getter: 'getLabel', setter: 'setLabel', testValue: '테스트트리거' }
];

scwin.testDataListToComponent = function() {
    console.log("=== [1] DataList → Component (초기 데이터 바인딩 확인) ===");
    var results = [];

    for (var i = 0; i < scwin.BIND_COMPONENTS.length; i++) {
        var item = scwin.BIND_COMPONENTS[i];
        var comp = listView1.getCellComponentById(0, item.compId);
        var dataValue = dataList1.getCellData(0, item.colId);
        var compValue = comp ? comp[item.getter]() : null;

        // image는 getSrc()에 origin이 붙어서 반환되므로 뒤에서부터 비교
        var match = (item.compId === 'image1')
            ? (compValue && compValue.slice(-dataValue.length) === dataValue)
            : (compValue == dataValue);

        results.push({
            component: item.compId,
            dataList: dataValue,
            component_val: compValue,
            result: match ? 'PASS' : 'FAIL'
        });
    }

    console.table(results);
};

scwin.testDataListToComponent2 = function() {
    console.log("=== [2] DataList → Component (DataList API 테스트) ===");
    scwin.btnInsertJSON_onclick();
    scwin.btnSetRowJSON_onclick();
    scwin.btnSetCellData_onclick();
    scwin.btnRemoveRow_onclick();
    scwin.btnRemoveRows_onclick();
    scwin.btnRemoveAll_onclick();
    scwin.btnSetJSON_onclick();  // 데이터 복구
};

scwin.testComponentToDataList = function() {
    console.log("=== [3] Component → DataList (Component → DataList 테스트) ===");
    var results = [];

    for (var i = 0; i < scwin.BIND_COMPONENTS.length; i++) {
        var item = scwin.BIND_COMPONENTS[i];
        var comp = listView1.getCellComponentById(0, item.compId);

        if (comp && comp[item.setter]) {
            comp[item.setter](item.testValue);
            var dataValue = dataList1.getCellData(0, item.colId);
            var match = (dataValue == item.testValue);

            results.push({
                component: item.compId,
                setValue: item.testValue,
                dataList: dataValue,
                result: match ? 'PASS' : 'FAIL'
            });
        }
    }

    console.table(results);
};

/**
 * 전체 테스트 실행
 */
scwin.runAllTests = function() {
    console.log("========================================");
    console.log("양방향 바인딩 테스트");
    console.log("========================================\n");

    scwin.testDataListToComponent();

    scwin.testDataListToComponent2();

    scwin.testComponentToDataList();

    console.log("\n========================================");
    console.log("테스트 완료");
    console.log("========================================");
};
